const loginResponse = page.waitForResponse(response => new URL(response.url()).pathname.endsWith('/v2.0/security/auth/login'), { timeout: 5000 }).catch(() => null)
await page.locator('.login-submit').click()
const loginResult = await loginResponse
if (!loginResult) {
  const diagnostic = await page.evaluate(() => ({
    title: document.title,
    bodyText: document.body?.innerText?.slice(0, 320),
    agreement: document.querySelector('.login-agreement')?.getAttribute('aria-checked'),
    inputs: [...document.querySelectorAll('input')].map(input => ({ placeholder: input.placeholder, value: input.value, type: input.type })),
  }))
  throw new Error(`Fake login did not request auth endpoint: ${JSON.stringify({ diagnostic, inputDetails, apiPaths, pageErrors, consoleErrors })}`)
}
if (loginResult.status() !== 200) throw new Error(`Screenshot login fixture returned HTTP ${loginResult.status()}`)
